mapper.select:
select cce.apply_id, cce.apply_time, cce.repay_amount, cce.order_id, cce.apply_status, cce.rule_id, cce.pay_status,cce.pay_time, cce.user_id, cce.invoice_status,cce.origin_cert_id,cce.target_cert_id, cce.create_by, cce.create_time, cce.update_by, cce.update_time, cce.del_flag, cce.version, cai.user_name,cai.school,cai.id_card,ccer.ruler_name, cai.competition_name,cai.competition_track_name,cai.second_level_name, ( SELECT GROUP_CONCAT(DISTINCT cait.user_name SEPARATOR '、') FROM competition_apply_info cait WHERE cait.team_code = cai.team_code AND cait.competition_role_name = '指导教师' AND cait.del_flag = '0' ) AS guide_teacher_name,cai.team_code from competition_cert_exchange_apply cce left join competition_apply_info cai on cce.user_id = cai.user_id and cai.del_flag = '0' left join competition_cert_exchange_rule ccer on cce.rule_id = ccer.rule_id and ccer.del_flag = '0' where cce.del_flag = '0'
and cce.apply_status = #{applyStatus}
and cce.rule_id = #{ruleId}
and cce.pay_status = #{payStatus}
and cce.user_id = #{userId}
and cce.invoice_status = #{invoiceStatus}
and cai.competition_name like concat('%', #{competitionName}, '%')
and cai.competition_track_name like concat('%', #{competitionTrackName}, '%')
and cai.second_level_name like concat('%', #{secondLevelName}, '%')
and cai.user_name like concat('%', #{userName}, '%')
AND EXISTS ( SELECT 1 FROM competition_apply_info cait WHERE cait.team_code = cai.team_code AND cait.competition_role_name = '指导教师' AND cait.del_flag = '0' AND cait.user_name LIKE concat('%', #{guideTeacherName}, '%') )
and cai.school in (select id from nationwide_college_info where school_name like concat('%', #{schoolName}, '%'))
order by cce.apply_time desc

mapper.update:
update competition_cert_exchange_apply
apply_time = #{applyTime}, repay_amount = #{repayAmount}, order_id = #{orderId}, apply_status = #{applyStatus}, rule_id = #{ruleId}, pay_status = #{payStatus}, pay_time = #{payTime}, user_id = #{userId}, invoice_status = #{invoiceStatus}, origin_cert_code = #{originCertCode}, origin_cert_id = #{originCertId}, target_cert_id = #{targetCertId}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, version = version+1,
where apply_id = #{applyId}

update competition_cert_exchange_apply
order_id = #{orderId}, apply_status = #{applyStatus}, pay_status = #{payStatus}, invoice_status = #{invoiceStatus}, pay_time = #{payTime}, version = version+1, update_time = now(),
where rule_id = #{ruleId} and user_id = #{userId}

update.foreach:
update competition_cert_exchange_apply
invoice_status = #{item.invoiceStatus}, version = version+1, update_time = now(),
where order_id = #{item.orderId} and user_id = #{item.userId}
